"use client";
import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { Search, ExternalLink, CheckCircle2, AlertCircle } from "lucide-react";
import { api } from "@/lib/api-client";
type Product={id:string;name:string;description:string;price:number|string;images?:{url:string}[];specifications?:Record<string,unknown>|null;category?:{name:string};};
function score(p:Product){let s=0;if(p.name?.trim())s+=20;if(p.name&&p.name.length>=20)s+=10;if(p.description?.trim())s+=20;if((p.description?.length??0)>=120)s+=10;if(p.images?.length)s+=15;if(p.specifications&&Object.keys(p.specifications).length)s+=10;if(p.category?.name)s+=10;if(Number(p.price)>0)s+=5;return Math.min(100,s);}
export default function SeoCenter(){const[products,setProducts]=useState<Product[]>([]);useEffect(()=>{void api.get<{products?:Product[];items?:Product[]}>("/api/products/me/list").then(r=>setProducts(r.products??r.items??[]));},[]);const average=useMemo(()=>products.length?Math.round(products.reduce((a,p)=>a+score(p),0)/products.length):0,[products]);return <div className="shell py-8"><Link href="/vendor/dashboard" className="text-sm font-semibold text-ember-600">← Dashboard</Link><div className="mt-3 flex flex-wrap items-end justify-between gap-4"><div><h1 className="text-2xl font-bold text-graphite-900">SEO Center</h1><p className="mt-1 max-w-2xl text-sm text-graphite-600">Improve how your products appear in Google and marketplace search.</p></div><a href="https://ttflstore.name.ng/api/seo/merchant.xml" target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 rounded-card border border-graphite-300 px-3 py-2 text-sm font-semibold">Merchant feed <ExternalLink className="h-4 w-4"/></a></div><div className="mt-6 rounded-card border border-graphite-200 bg-white p-5"><div className="flex items-center gap-3"><Search className="h-5 w-5 text-ember-600"/><div><p className="text-sm font-semibold">Catalog SEO health</p><p className="text-2xl font-bold">{average}/100</p></div></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-graphite-100"><div className="h-full bg-ember-600" style={{width:`${average}%`}}/></div><p className="mt-3 text-xs text-graphite-600">Scores reward strong titles, useful descriptions, images, specifications, categories and valid pricing.</p></div><div className="mt-6 space-y-3">{products.map(p=>{const s=score(p);const checks=[!!p.name,!!p.description&&p.description.length>=120,!!p.images?.length,!!p.specifications&&Object.keys(p.specifications).length>0,!!p.category?.name];return <div key={p.id} className="rounded-card border border-graphite-200 bg-white p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="font-semibold text-graphite-900">{p.name}</p><p className="text-xs text-graphite-600">{s}/100 SEO score</p></div><div className="flex items-center gap-2 text-xs">{checks.map((ok,i)=>ok?<CheckCircle2 key={i} className="h-4 w-4 text-verified-600"/>:<AlertCircle key={i} className="h-4 w-4 text-gold-600"/>)}</div></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-graphite-100"><div className="h-full bg-ember-600" style={{width:`${s}%`}}/></div></div>})}{!products.length&&<div className="rounded-card border border-dashed border-graphite-300 p-8 text-center text-sm text-graphite-600">No products to analyze yet.</div>}</div></div>}
